    {
      "id": "SG-BLOB-SCHEDULE",
      "name": "Blob Schedule Configuration (EIP-7892)",
      "description": "Defines the BLOB_SCHEDULE configuration table that governs the maximum number of blobs permitted per block at any given epoch. This is a new mechanism in Fulu (via EIP-7892) that enables 'Blob Parameter Only Hardforks', allowing the blob limit to be adjusted via a schedule without requiring a full consensus-layer hard fork. The schedule is a list of (epoch, max_blobs_per_block) entries that activate at their respective epochs.",
      "invariants": [
        {
          "id": "INV-BLOB-SCHED-001",
          "text": "There MUST NOT exist multiple blob schedule entries with the same epoch value. Each epoch in the schedule must be unique."
        },
        {
          "id": "INV-BLOB-SCHED-002",
          "text": "The epoch value in each blob schedule entry MUST be greater than or equal to FULU_FORK_EPOCH."
        },
        {
          "id": "INV-BLOB-SCHED-003",
          "text": "The max_blobs_per_block value in each blob schedule entry MUST be less than or equal to MAX_BLOB_COMMITMENTS_PER_BLOCK."
        },
        {
          "id": "INV-BLOB-SCHED-004",
          "text": "The blob schedule entries SHOULD be sorted by epoch in ascending order."
        },
        {
          "id": "INV-BLOB-SCHED-005",
          "text": "The blob schedule MAY be empty. If empty, the system falls back to the Electra-era default blob parameters."
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-BLOB-SCHED-001",
          "name": "BLOB_SCHEDULE",
          "type": "List[BlobScheduleEntry]",
          "value": "[{epoch: 412672, max_blobs_per_block: 15}, {epoch: 419072, max_blobs_per_block: 21}]",
          "description": "The configuration table mapping epochs to maximum blob counts per block. Epoch 412672 (Dec 9, 2025) sets max to 15; epoch 419072 (Jan 7, 2026) raises max to 21."
        }
      ],
      "data_structures": [],
      "pre_conditions": [],
      "post_conditions": [],
      "state_transitions": [
        {
          "id": "ST-BLOB-SCHED-001",
          "from_state": "Epoch < 412672 (pre-schedule)",
          "to_state": "Epoch >= 412672: max_blobs_per_block = 15",
          "trigger": "Epoch reaches 412672",
          "description": "At epoch 412672, the first blob schedule entry activates, setting the maximum blobs per block to 15."
        },
        {
          "id": "ST-BLOB-SCHED-002",
          "from_state": "Epoch >= 412672: max_blobs_per_block = 15",
          "to_state": "Epoch >= 419072: max_blobs_per_block = 21",
          "trigger": "Epoch reaches 419072",
          "description": "At epoch 419072, the second blob schedule entry activates, raising the maximum blobs per block to 21."
        }
      ],
      "security_notes": [
        "The schedule must be validated at client startup to ensure no duplicate epochs exist, preventing ambiguity in which limit applies.",
        "The upper bound constraint (max_blobs_per_block <= MAX_BLOB_COMMITMENTS_PER_BLOCK) prevents schedule entries from exceeding the SSZ container capacity, which would cause serialization failures.",
        "An empty schedule falls back to Electra defaults, ensuring backward compatibility if no Fulu-era blob limits are configured."
      ]
    },
    {
      "id": "SG-BLOB-PARAMETERS",
      "name": "BlobParameters Data Structure and Lookup (EIP-7892)",
      "description": "Defines the BlobParameters dataclass and the get_blob_parameters function that resolves the active blob parameters for a given epoch. The function iterates the BLOB_SCHEDULE in reverse epoch order and returns the first entry whose epoch is <= the queried epoch. If no matching entry is found, it falls back to Electra-era defaults.",
      "invariants": [
        {
          "id": "INV-BLOB-PARAMS-001",
          "text": "For any epoch E, get_blob_parameters(E) must return exactly one BlobParameters instance. The function is total and always returns a value."
        },
        {
          "id": "INV-BLOB-PARAMS-002",
          "text": "If no BLOB_SCHEDULE entry has an epoch <= E, the function returns BlobParameters(ELECTRA_FORK_EPOCH, MAX_BLOBS_PER_BLOCK_ELECTRA) as the fallback."
        },
        {
          "id": "INV-BLOB-PARAMS-003",
          "text": "The function returns the most recent (highest epoch) schedule entry whose epoch is <= the queried epoch, implementing a 'latest applicable' lookup."
        }
      ],
      "functions": [
        {
          "id": "FN-BLOB-PARAMS-001",
          "signature": "get_blob_parameters(epoch: Epoch) -> BlobParameters",
          "description": "Returns the blob parameters for a given epoch by iterating the BLOB_SCHEDULE sorted in descending epoch order and returning the first entry where epoch >= entry.EPOCH. Falls back to Electra defaults if no match.",
          "pseudo_logic": "for entry in sorted(BLOB_SCHEDULE, key=epoch, reverse=True): if epoch >= entry.EPOCH: return BlobParameters(entry.EPOCH, entry.MAX_BLOBS_PER_BLOCK); return BlobParameters(ELECTRA_FORK_EPOCH, MAX_BLOBS_PER_BLOCK_ELECTRA)"
        }
      ],
      "state_variables": [],
      "data_structures": [
        {
          "id": "DS-BLOB-PARAMS-001",
          "name": "BlobParameters",
          "type": "dataclass",
          "fields": [
            {"name": "epoch", "type": "Epoch", "description": "The epoch at which these blob parameters became active."},
            {"name": "max_blobs_per_block", "type": "uint64", "description": "The maximum number of blobs allowed per block under these parameters."}
          ],
          "description": "A dataclass representing the blob parameters active at a particular epoch. Used as the return type of get_blob_parameters."
        }
      ],
      "pre_conditions": [
        {
          "id": "PRE-BLOB-PARAMS-001",
          "text": "The BLOB_SCHEDULE configuration must be loaded and available when get_blob_parameters is called."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-BLOB-PARAMS-001",
          "text": "The returned BlobParameters.epoch is always <= the queried epoch."
        },
        {
          "id": "POST-BLOB-PARAMS-002",
          "text": "The returned BlobParameters.max_blobs_per_block is always <= MAX_BLOB_COMMITMENTS_PER_BLOCK (given the schedule invariant INV-BLOB-SCHED-003 holds)."
        }
      ],
      "state_transitions": [],
      "security_notes": [
        "The reverse-sorted iteration ensures the most recent applicable schedule entry is returned first, preventing stale parameters from being used.",
        "The Electra fallback guarantees the function never returns an undefined or zero blob limit, which could halt block production.",
        "If the BLOB_SCHEDULE is malformed (e.g., contains entries with epoch < FULU_FORK_EPOCH), the fallback path may be reached unexpectedly."
      ]
    },
    {
      "id": "SG-PROCESS-EXECUTION-PAYLOAD",
      "name": "Modified process_execution_payload (EIP-7892)",
      "description": "The process_execution_payload function is modified in Fulu (via EIP-7892) to use the dynamic blob schedule for validating blob KZG commitment counts. Instead of a static constant, it now calls get_blob_parameters(get_current_epoch(state)).max_blobs_per_block to determine the maximum allowed blob commitments. The function also verifies parent hash consistency, prev_randao, timestamp, execution payload validity, and caches the execution payload header.",
      "invariants": [
        {
          "id": "INV-EXEC-PAYLOAD-001",
          "text": "payload.parent_hash must equal state.latest_execution_payload_header.block_hash, ensuring execution payload chain continuity."
        },
        {
          "id": "INV-EXEC-PAYLOAD-002",
          "text": "payload.prev_randao must equal get_randao_mix(state, get_current_epoch(state)), binding the execution payload to the current consensus randomness."
        },
        {
          "id": "INV-EXEC-PAYLOAD-003",
          "text": "payload.timestamp must equal compute_time_at_slot(state, state.slot), ensuring execution and consensus layers agree on time."
        },
        {
          "id": "INV-EXEC-PAYLOAD-004",
          "text": "len(body.blob_kzg_commitments) must be <= get_blob_parameters(get_current_epoch(state)).max_blobs_per_block. This is the EIP-7892 modification that replaces the former static blob limit check."
        },
        {
          "id": "INV-EXEC-PAYLOAD-005",
          "text": "The execution payload must pass execution_engine.verify_and_notify_new_payload, which validates the payload against the execution layer rules."
        }
      ],
      "functions": [
        {
          "id": "FN-EXEC-PAYLOAD-001",
          "signature": "process_execution_payload(state: BeaconState, body: BeaconBlockBody, execution_engine: ExecutionEngine) -> None",
          "description": "Processes the execution payload within a beacon block body. Validates parent hash, prev_randao, timestamp, blob commitment count (using dynamic blob schedule per EIP-7892), and execution engine validity. On success, caches the execution payload header in the beacon state.",
          "pseudo_logic": "assert payload.parent_hash == state.latest_execution_payload_header.block_hash; assert payload.prev_randao == get_randao_mix(state, get_current_epoch(state)); assert payload.timestamp == compute_time_at_slot(state, state.slot); assert len(body.blob_kzg_commitments) <= get_blob_parameters(get_current_epoch(state)).max_blobs_per_block; versioned_hashes = [kzg_commitment_to_versioned_hash(c) for c in body.blob_kzg_commitments]; assert execution_engine.verify_and_notify_new_payload(NewPayloadRequest(...)); state.latest_execution_payload_header = ExecutionPayloadHeader(...);"
        }
      ],
      "state_variables": [],
      "data_structures": [],
      "pre_conditions": [
        {
          "id": "PRE-EXEC-PAYLOAD-001",
          "text": "The beacon state must contain a valid latest_execution_payload_header with a block_hash that matches the payload's parent_hash."
        },
        {
          "id": "PRE-EXEC-PAYLOAD-002",
          "text": "The RANDAO mix for the current epoch must be available in the beacon state."
        },
        {
          "id": "PRE-EXEC-PAYLOAD-003",
          "text": "The execution engine must be available and responsive for payload verification."
        },
        {
          "id": "PRE-EXEC-PAYLOAD-004",
          "text": "The BLOB_SCHEDULE must be configured such that get_blob_parameters returns valid parameters for the current epoch."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-EXEC-PAYLOAD-001",
          "text": "state.latest_execution_payload_header is updated to an ExecutionPayloadHeader derived from the validated payload, including parent_hash, fee_recipient, state_root, receipts_root, logs_bloom, prev_randao, block_number, gas_limit, gas_used, timestamp, extra_data, base_fee_per_gas, block_hash, transactions_root (hashed), withdrawals_root (hashed), blob_gas_used, and excess_blob_gas."
        },
        {
          "id": "POST-EXEC-PAYLOAD-002",
          "text": "The execution engine has been notified of the new payload and has validated it."
        }
      ],
      "state_transitions": [
        {
          "id": "ST-EXEC-PAYLOAD-001",
          "from_state": "state.latest_execution_payload_header = previous header",
          "to_state": "state.latest_execution_payload_header = ExecutionPayloadHeader derived from validated payload",
          "trigger": "Successful processing of a beacon block containing an execution payload",
          "description": "On successful validation of all assertions (parent hash, randao, timestamp, blob count, execution engine), the beacon state's latest_execution_payload_header is replaced with a new header constructed from the current payload's fields."
        }
      ],
      "security_notes": [
        "The dynamic blob limit (via get_blob_parameters) means the maximum allowed blobs can change at epoch boundaries without a hard fork. Validators must ensure their BLOB_SCHEDULE is consistent with the network's configuration.",
        "The parent_hash check ensures execution payload chain integrity. A mismatch indicates a fork or invalid block.",
        "The prev_randao binding prevents execution payload reuse across different randomness contexts.",
        "The execution engine verify_and_notify call is the critical CL-EL interface point. Failure here rejects the entire block."
      ]
    },
    {
      "id": "SG-BEACON-STATE-CONTAINER",
      "name": "Modified BeaconState Container (EIP-7917)",
      "description": "The BeaconState SSZ container is extended in Fulu with a new field 'proposer_lookahead' (via EIP-7917). This field is a Vector of ValidatorIndex with length (MIN_SEED_LOOKAHEAD + 1) * SLOTS_PER_EPOCH, storing pre-computed proposer indices for the current epoch and the lookahead period. proposer_lookahead[0] is the proposer for the first slot of the current epoch, and so forth.",
      "invariants": [
        {
          "id": "INV-STATE-001",
          "text": "The length of proposer_lookahead is always exactly (MIN_SEED_LOOKAHEAD + 1) * SLOTS_PER_EPOCH. With MIN_SEED_LOOKAHEAD = 1, this is 2 * SLOTS_PER_EPOCH = 64 entries (assuming SLOTS_PER_EPOCH = 32)."
        },
        {
          "id": "INV-STATE-002",
          "text": "proposer_lookahead[i] must be a valid ValidatorIndex corresponding to an active validator at the epoch in which slot i falls."
        },
        {
          "id": "INV-STATE-003",
          "text": "proposer_lookahead[0] corresponds to the proposer of the first slot of the current epoch. proposer_lookahead[SLOTS_PER_EPOCH] corresponds to the proposer of the first slot of the next epoch."
        }
      ],
