          {"id": "INV-BLOB-SCHED-003", "text": "The max_blobs_per_block value in each blob schedule entry MUST be less than or equal to MAX_BLOB_COMMITMENTS_PER_BLOCK."},
          {"id": "INV-BLOB-SCHED-004", "text": "The blob schedule entries SHOULD be sorted by epoch in ascending order."},
          {"id": "INV-BLOB-SCHED-005", "text": "The blob schedule MAY be empty. If empty, the system falls back to the Electra-era default blob parameters."}
