        "description": "Defines the step-by-step ECDSA signature verification algorithm for secp256r1. After input validation passes, the algorithm computes the modular inverse of s, recovers a point R', checks if R' is the point at infinity, and compares the x-coordinate of R' with r modulo n.",
        "invariants": [
          {"id": "INV-015", "text": "The comparison of r' with r MUST use modular reduction: r' = R'.x (mod n), not direct integer comparison. This is a security fix over RIP-7212."},
          {"id": "INV-016", "text": "If R' is the point at infinity, the precompile MUST return empty bytes. This is a security fix over RIP-7212."}
        ],
        "preconditions": [
          {"id": "PRE-007", "text": "All five input validation checks from SG-006 must have passed."}
        ],
        "postconditions": [
          {"id": "POST-005", "text": "Returns 0x0000...0001 (32 bytes) if and only if R'.x mod n == r."},
          {"id": "POST-006", "text": "Returns empty bytes if R' is the point at infinity or if R'.x mod n != r."}
        ],
        "functions": [
          {
            "id": "FN-003",
            "signature": "verify(h, r, s, Q) -> bool",
            "description": "Core ECDSA verification: compute s1 = s^(-1) mod n; R' = (h * s1) * G + (r * s1) * Q; if R' is infinity, fail; if R'.x mod n == r, success; else fail.",
            "pseudocode": [
              "s1 = s^(-1) (mod n)",
              "R' = (h * s1) * G + (r * s1) * (qx, qy)",
              "if R' is the point at infinity: return failure",
              "r' = R'.x",
              "if r' ≡ r (mod n): return success (0x0000...0001)",
              "else: return failure (empty)"
            ]
          }
        ],
