    {
      "id": "SG-COMPUTE-FORK-DIGEST",
      "name": "Modified compute_fork_digest (EIP-7892)",
      "description": "The compute_fork_digest function is modified in Fulu (via EIP-7892) to incorporate blob parameters into the fork digest computation. The base fork digest (derived from fork version and genesis validators root) is XOR'd with a hash of the current blob parameters (epoch + max_blobs_per_block). This causes the fork digest to change whenever blob parameters change, enabling p2p layer domain separation for blob-parameter-only forks without requiring a new fork version.",
      "invariants": [
        {
          "id": "INV-FORK-DIGEST-001",
          "text": "The fork digest changes whenever either the fork version OR the active blob parameters (epoch, max_blobs_per_block) change. Two nodes with different active blob parameters will compute different fork digests."
        },
        {
          "id": "INV-FORK-DIGEST-002",
          "text": "The fork digest is 4 bytes (32 bits), derived from the first 4 bytes of the XOR of the base digest and the blob parameter hash."
        }
      ],
      "functions": [
        {
          "id": "FN-FORK-DIGEST-001",
          "signature": "compute_fork_digest(genesis_validators_root: Root, epoch: Epoch) -> ForkDigest",
          "description": "Computes the 4-byte fork digest for p2p domain separation. In Fulu, the base digest (from fork version and genesis_validators_root) is XOR'd with hash(uint_to_bytes(blob_parameters.epoch) + uint_to_bytes(blob_parameters.max_blobs_per_block)), and truncated to 4 bytes.",
          "pseudo_logic": "fork_version = compute_fork_version(epoch); base_digest = compute_fork_data_root(fork_version, genesis_validators_root); blob_parameters = get_blob_parameters(epoch); return ForkDigest(bytes(xor(base_digest, hash(uint_to_bytes(blob_parameters.epoch) + uint_to_bytes(blob_parameters.max_blobs_per_block))))[:4])"
        }
      ],
      "state_variables": [],
      "data_structures": [],
      "pre_conditions": [
        {
          "id": "PRE-FORK-DIGEST-001",
          "text": "The genesis_validators_root must be known and fixed for the network."
        },
        {
          "id": "PRE-FORK-DIGEST-002",
          "text": "The BLOB_SCHEDULE must be configured such that get_blob_parameters returns valid parameters for the queried epoch."
        }
      ],
      "post_conditions": [
        {
          "id": "POST-FORK-DIGEST-001",
          "text": "The returned ForkDigest is exactly 4 bytes and uniquely identifies the combination of fork version and active blob parameters."
        }
      ],
      "state_transitions": [
        {
          "id": "ST-FORK-DIGEST-001",
          "from_state": "Fork digest D1 with blob parameters (epoch_a, max_a)",
          "to_state": "Fork digest D2 with blob parameters (epoch_b, max_b)",
          "trigger": "A new BLOB_SCHEDULE entry activates at epoch_b, changing the active blob parameters",
          "description": "When a blob schedule entry activates at a new epoch, the fork digest changes even without a consensus fork version change. Nodes on the network transition to a new fork digest, causing p2p topic segregation."
        }
      ],
      "security_notes": [
        "The XOR-and-hash approach ensures that the blob parameters are cryptographically mixed into the fork digest, preventing accidental collisions.",
        "A fork digest change at blob schedule boundaries forces p2p network re-subscription, which could cause brief connectivity disruptions if nodes have inconsistent BLOB_SCHEDULE configurations.",
        "The 4-byte truncation provides 2^32 possible digests, sufficient for practical fork/chain separation but not cryptographically collision-resistant in isolation.",
        "Nodes with mismatched BLOB_SCHEDULE configurations will compute different fork digests and be unable to communicate on gossip topics, effectively partitioning the network."
      ]
    },
