    {
      "id": "SG-PROCESS-PROPOSER-LOOKAHEAD",
      "name": "New process_proposer_lookahead (EIP-7917)",
      "description": "A new epoch processing function that updates the proposer_lookahead field in the beacon state. It performs a shift-and-fill operation: proposer indices for the earliest epoch in the lookahead are shifted out, and new proposer indices for the latest epoch in the lookahead window are computed and appended. With MIN_SEED_LOOKAHEAD = 1, at the start of epoch N, this computes proposers for epoch N+2 (current_epoch + MIN_SEED_LOOKAHEAD + 1).",
      "invariants": [
        {
          "id": "INV-PROPOSER-LOOKAHEAD-001",
          "text": "After execution, the first (len(proposer_lookahead) - SLOTS_PER_EPOCH) entries contain the shifted-forward proposer indices (i.e., the proposers that were previously at positions SLOTS_PER_EPOCH through the end)."
        },
        {
          "id": "INV-PROPOSER-LOOKAHEAD-002",
          "text": "After execution, the last SLOTS_PER_EPOCH entries contain freshly computed proposer indices for epoch (get_current_epoch(state) + MIN_SEED_LOOKAHEAD + 1)."
        },
        {
          "id": "INV-PROPOSER-LOOKAHEAD-003",
          "text": "The total length of proposer_lookahead remains unchanged at (MIN_SEED_LOOKAHEAD + 1) * SLOTS_PER_EPOCH."
        }
      ],
      "functions": [
        {
          "id": "FN-PROPOSER-LOOKAHEAD-001",
          "signature": "process_proposer_lookahead(state: BeaconState) -> None",
          "description": "Updates the proposer_lookahead by shifting out the earliest epoch's proposers and filling in new proposers for the latest lookahead epoch. Steps: (1) Compute last_epoch_start = len(proposer_lookahead) - SLOTS_PER_EPOCH. (2) Shift proposer_lookahead[SLOTS_PER_EPOCH:] to proposer_lookahead[:last_epoch_start]. (3) Compute proposers for epoch (current_epoch + MIN_SEED_LOOKAHEAD + 1). (4) Fill proposer_lookahead[last_epoch_start:] with the new proposer indices.",
          "pseudo_logic": "last_epoch_start = len(state.proposer_lookahead) - SLOTS_PER_EPOCH; state.proposer_lookahead[:last_epoch_start] = state.proposer_lookahead[SLOTS_PER_EPOCH:]; last_epoch_proposers = get_beacon_proposer_indices(state, Epoch(get_current_epoch(state) + MIN_SEED_LOOKAHEAD + 1)); state.proposer_lookahead[last_epoch_start:] = last_epoch_proposers"
        }
      ],
      "state_variables": [],
      "data_structures": [],
      "pre_conditions": [
        {
          "id": "PRE-PROPOSER-LOOKAHEAD-001",
          "text": "state.proposer_lookahead must be initialized with valid proposer indices (from genesis or a previous epoch transition)."
        },
