          "id": "POST-PROPOSER-LOOKAHEAD-001",
          "text": "state.proposer_lookahead[0:SLOTS_PER_EPOCH] contains proposer indices for the next epoch (epoch N+1 when called at the end of epoch N)."
        },
        {
          "id": "POST-PROPOSER-LOOKAHEAD-002",
          "text": "state.proposer_lookahead[SLOTS_PER_EPOCH:] contains proposer indices for epoch N+2 (the newly computed lookahead epoch)."
        },
        {
          "id": "POST-PROPOSER-LOOKAHEAD-003",
          "text": "The proposer indices that were in positions [0, SLOTS_PER_EPOCH) before execution (current epoch's proposers) are no longer in the lookahead, as they have been shifted out."
        }
      ],
      "state_transitions": [
        {
          "id": "ST-PROPOSER-LOOKAHEAD-001",
          "from_state": "proposer_lookahead = [epoch_N_proposers | epoch_N+1_proposers]",
          "to_state": "proposer_lookahead = [epoch_N+1_proposers | epoch_N+2_proposers]",
          "trigger": "process_proposer_lookahead(state) called at end of epoch N",
          "description": "The lookahead window slides forward by one epoch: epoch N's proposers are evicted, epoch N+1's proposers shift to the front, and epoch N+2's proposers are freshly computed and placed at the end."
        }
      ],
      "security_notes": [
